# ╔═╡ ce177b4e-0837-48a3-9261-a7ab3aa2e4f9
md"""
Compare with your predictions: larger ``κ`` changes the speed of return, and nonzero ``ξ`` adds irregular variance changes. Before setting ``ρ=-0.7``, predict which direction of price shock will tend to accompany a rising-variance shock.

As a new test, try starting below the target, or set ``κ=0``. Say which term changes before looking at the path. A single random path can obscure the tendency; compare several seeds.

### Try the same parameters across several expiries

The black line is the Heston model with the parameter values above. The colored dots are option quotes expressed as implied volatility. Keep the model sliders fixed and switch expiry below to test the same parameters at three horizons.


Expiry to compare: $(@bind h_fit_exp Select([d => Dates.format(d, "d u yyyy") for d in FIT_EXPIRIES], default=FIT_EXPIRIES[1]))

The **random seed** selects a reproducible set of shocks. Keep it fixed when changing a parameter so you can compare the same realization of randomness.

With negative ``ρ``, a shock raising variance tends to accompany a price fall. This is the **leverage effect** in equity models; it does not happen on every move. The paths are continuous—volatility can rise rapidly, but this model has no literal jumps.

The comparison reports **RMSE**, root mean squared error: square each model-minus-market IV difference, average, then take the square root. An error of 1 IV point means, for example, 21% instead of 20%. The valid-count label reports how many quotes produced usable numerical values.
"""

# ╔═╡ 7e570ddf-8270-40a8-a369-b584ff5e9ff0
begin
    abstract type PriceModel end
    struct BlackScholes <: PriceModel
        sigma::Float64
    end
    struct Heston <: PriceModel
        v0::Float64; kappa::Float64; theta::Float64; xi::Float64; rho::Float64
    end
    struct RoughBergomi <: PriceModel
        v0::Float64; eta::Float64; H::Float64; rho::Float64
    end

    function simulate(m::BlackScholes; S0=SPOT, n=250, T=1.0, seed=7)
        rng = MersenneTwister(seed); dt = T / n
        S = fill(S0, n + 1); v = fill(m.sigma^2, n + 1)
        for i in 1:n
            S[i+1] = S[i] * exp(-0.5v[i] * dt + sqrt(v[i] * dt) * randn(rng))
        end
        (; t=collect(range(0, T, length=n + 1)), S, v)
    end

    function simulate(m::Heston; S0=SPOT, n=250, T=1.0, seed=7)
        rng = MersenneTwister(seed); dt = T / n
        S = fill(S0, n + 1); v = zeros(n + 1); v[1] = m.v0; raw = m.v0
        for i in 1:n
            z, b = randn(rng, 2)
            w = m.rho * z + sqrt(1 - m.rho^2) * b      # correlated price shock
            vp = max(raw, 0.0)
            S[i+1] = S[i] * exp(-0.5vp * dt + sqrt(vp * dt) * w)
            raw += m.kappa * (m.theta - vp) * dt + m.xi * sqrt(vp * dt) * z   # full-truncation Euler
            v[i+1] = max(raw, 0.0)
        end
        (; t=collect(range(0, T, length=n + 1)), S, v)
    end

    function simulate(m::RoughBergomi; S0=SPOT, n=250, T=1.0, seed=7)
        rng = MersenneTwister(seed); dt = T / n
        t = collect(range(0, T, length=n + 1))
        z = randn(rng, n); b = randn(rng, n)
        p = m.H + 0.5
        w = [sqrt(2m.H) * ((k * dt)^p - ((k - 1) * dt)^p) / (p * dt) for k in 1:n]   # kernel weights
        Y = zeros(n + 1); q = zeros(n + 1)
        for i in 1:n                                   # O(N²): every step revisits the history
            Y[i+1] = sum(w[i-j+1] * sqrt(dt) * z[j] for j in 1:i)
            q[i+1] = dt * sum(abs2, view(w, 1:i))
        end
        v = m.v0 .* exp.(m.eta .* Y .- 0.5m.eta^2 .* q)
        S = fill(S0, n + 1)
        for i in 1:n
            S[i+1] = S[i] * exp(-0.5v[i] * dt + sqrt(v[i] * dt) * (m.rho * z[i] + sqrt(1 - m.rho^2) * b[i]))
        end
        (; t, S, v)
    end

    function mark_outside!(p,t,y,lo,hi)
        below=findall(v->isfinite(v) && v<lo,y)
        above=findall(v->isfinite(v) && v>hi,y)
        n=length(below)+length(above)
        if n>0
            !isempty(below) && scatter!(p,t[below],fill(lo,length(below)),marker=:dtriangle,ms=3,color=RED,label=false)
            !isempty(above) && scatter!(p,t[above],fill(hi,length(above)),marker=:utriangle,ms=3,color=RED,label=false)
            annotate!(p,t[1]+0.02(t[end]-t[1]),hi-0.08(hi-lo),text("$n points beyond fixed view",8,:left,RED))
        end
        p
    end

    function path_panels(m::PriceModel; seed=7, T=1.0)
        x = simulate(m; seed, T)
        a = plot(x.t, x.S, color=BLUE, label="SPY (simulated)", ylabel="price (\$)", title="Price",xlims=(0,T),ylims=(0,2SPOT),widen=false)
        b = plot(x.t, 100 .* sqrt.(x.v), color=ORANGE, label="volatility", xlabel="years",
            ylabel="volatility (%)", title="Size of the shocks", xlims=(0,T),ylim=(0,100),widen=false)
        mark_outside!(a,x.t,x.S,0,2SPOT)
        mark_outside!(b,x.t,100sqrt.(x.v),0,100)
        plot(a, b, layout=(2, 1), size=(860, 480))
    end
end;

