# ╔═╡ e27a984d-6548-41d0-bfcd-9eb1a7cad415
let
    lag = range(0.003, 1.0, length=300)
    a = plot(lag, lag .^ (hurst - 0.5), color=PURPLE, label="H = $hurst", xlabel="age of shock (years)",
        ylabel="weight (vs 1-year-old shock)", title="How much a past shock still matters",xlims=(0,1),ylims=(0,15),widen=false)
    hline!(a, [1.0], color=GRAY, ls=:dash, label="H = 0.5")
    x1 = simulate(RoughBergomi(0.03, 1.5, 0.5, -0.7); seed=h_seed)
    x2 = simulate(RoughBergomi(0.03, 1.5, hurst, -0.7); seed=h_seed)
    b = plot(x1.t, 100sqrt.(x1.v), color=GRAY, label="H = 0.5", xlabel="years", ylabel="volatility (%)",
        title="Same shocks, different memory",xlims=(0,1),ylims=(0,100),widen=false)
    plot!(b, x2.t, 100sqrt.(x2.v), color=PURPLE, label="H = $hurst")
    mark_outside!(b,x2.t,100sqrt.(x2.v),0,100)
    mark_outside!(b,x1.t,100sqrt.(x1.v),0,100)
    plot(a, b, layout=(1, 2), size=(1000, 430))
end

# ╔═╡ 2e89f80a-d4ac-4b83-8192-266dc991d0f2
let
    if cost_run == 0
        md"Click to measure this machine. The result is not a model-accuracy comparison."
    else
        grids=[64,128,256,512]
        models=[BlackScholes(0.2),Heston(0.04,2.0,0.04,0.3,-0.7),RoughBergomi(0.04,1.0,0.1,-0.7)]
        labels=["Black–Scholes","Heston","Rough Bergomi"]
        ms=zeros(3,length(grids))
        for (j,m) in enumerate(models), (k,n) in enumerate(grids)
            simulate(m;n=n) # warm up before timing
            samples=Float64[]
            for rep in 1:5
                elapsed=@elapsed begin
                    for seed in 1:5
                        simulate(m;n=n,seed=seed)
                    end
                end
                push!(samples,1000elapsed)
            end
            ms[j,k]=median(samples)
        end
        a=plot(xscale=:log2,yscale=:log10,xticks=(grids,string.(grids)),xlabel="Steps per path",ylabel="Median time (ms; 5 paths)",title="Measured after warm-up")
        b=plot(xscale=:log2,yscale=:log2,xticks=(grids,string.(grids)),xlabel="Steps per path",ylabel="Time relative to 64 steps",title="Scaling of these implementations")
        for j in 1:3
            plot!(a,grids,ms[j,:],marker=:circle,label=labels[j])
            plot!(b,grids,ms[j,:]./ms[j,1],marker=:circle,label=labels[j])
        end
        plot!(b,grids,grids./64,label="Linear work",ls=:dash,color=GRAY)
        plot!(b,grids,(grids./64).^2,label="Quadratic work",ls=:dot,color=:black)
        plot(a,b,layout=(1,2),size=(950,380))
    end
end

