# ╔═╡ 1d53434b-b881-49b9-ae27-0da702f06b90
begin
    chain = map(eachsplit(strip(CHAIN_CSV), '\n')) do l
        f = split(l, ',')
        (expiry=Date(f[1]), type=f[2][1], K=parse(Float64, f[3]), bid=parse(Float64, f[4]),
         ask=parse(Float64, f[5]), volume=parse(Int, f[6]))
    end
    function parse_hist(s)
        rows = [split(l, ',') for l in eachsplit(strip(s), '\n')]
        (date=[Date(r[1]) for r in rows], close=[parse(Float64, r[2]) for r in rows])
    end
    spy_hist = parse_hist(SPY_HIST_CSV)
    vix_hist = parse_hist(VIX_CSV)
end;

