intro_quote = only(filter(o -> o.expiry == intro_exp && o.type == intro_type && o.K == intro_K, chain));

# ╔═╡ a28defe3-9bf0-4273-9247-6f57a5e5a5ab
let
    yr(d) = year(d) + (dayofyear(d) - 1) / 365
    x = yr.(vix_hist.date)
    p = plot(x, vix_hist.close, color=RED, fillrange=0, fillalpha=0.15, lw=1,
        label="VIX (daily close)", ylabel="Annualized implied volatility (%)", title="Volatility moves — and clusters",
        size=(860, 440), legend=:outerbottom, legend_column=-1, ylim=(0, 105), xticks=2008:2:2026)
    hline!(p, [mean(vix_hist.close)], color=:black, ls=:dash, lw=1.5,
        label="Flat reference: sample mean ( $(round(mean(vix_hist.close), digits=1)))")
    events = [(Date(2008, 11, 20), "2008 crisis"), (Date(2011, 8, 8), "US downgrade"),
        (Date(2015, 8, 24), "China deval."), (Date(2018, 2, 5), "Volmageddon"),
        (Date(2020, 3, 16), "COVID"), (Date(2022, 3, 7), "Inflation"), (Date(2025, 4, 8), "Tariff shock")]
    for (d, lab) in events
        w = findall(t -> abs(Dates.value(t - d)) <= 30, vix_hist.date)
        isempty(w) && continue
        i = w[argmax(vix_hist.close[w])]
        annotate!(p, x[i], vix_hist.close[i] + 5, text(lab, 8, :center))
    end
    p
end

# ╔═╡ 3eabedcb-baa8-4dd4-88bd-64072bcfbe01
let
    r = diff(log.(spy_hist.close))
    d = spy_hist.date[2:end]
    up = r .> 0
    a = plot(d[up], 100r[up], seriestype=:sticks, color=GREEN, lw=1, label=false,
        ylabel="daily return (%)", title="SPY daily moves, last 5 years: calm and wild periods cluster")
    plot!(a, d[.!up], 100r[.!up], seriestype=:sticks, color=RED, lw=1, label=false)
    z = (r .- mean(r)) ./ std(r)
    zmax = max(8,ceil(Int,maximum(abs,z)))
    b = histogram(z, bins=-zmax:0.25:zmax, normalize=:pdf, color=BLUE, lw=0, alpha=0.6, label="SPY",
        yscale=:log10, ylim=(1e-5, 1), xlabel="daily move (in standard deviations)", ylabel="Probability density (log scale)",
        title="Big moves are far more common than a bell curve says", legend=:topright)
    x = -zmax:0.05:zmax
    plot!(b, x, exp.(-x .^ 2 ./ 2) ./ sqrt(2π), color=:black, lw=2, label="normal (Black–Scholes)")
    n4 = count(abs.(z) .> 4)
    expected = length(z) * (1 - erf(4 / sqrt(2)))
    annotate!(b, -7.6, 0.15, text("moves beyond 4σ:\nobserved $(n4)\nbell curve: $(round(expected, digits=2))", 9, :left))
    plot(a, b, layout=(2, 1), size=(860, 640))
end

# ╔═╡ c0398710-8976-4334-a281-7efdae849217
begin
    Φ(x) = 0.5 * (1 + erf(x / sqrt(2)))
    mid(o) = (o.bid + o.ask) / 2
    yearfrac(d) = Dates.value(d - ASOF) / 365

    "Black–Scholes (Black-76) price on forward F with discount factor D."
    function black(F, K, T, σ, D; call=true)
        σ <= 0 && return D * max(call ? F - K : K - F, 0)
        d1 = (log(F / K) + σ^2 * T / 2) / (σ * sqrt(T)); d2 = d1 - σ * sqrt(T)
        call ? D * (F * Φ(d1) - K * Φ(d2)) : D * (K * Φ(-d2) - F * Φ(-d1))
    end

    "Invert Black–Scholes by bisection: the σ that reproduces `price`."
    function implied_vol(price, F, K, T, D; call=true)
        lower = D * max(call ? F - K : K - F, 0)
        upper = D * (call ? F : K)
        (!isfinite(price) || T <= 0 || price <= lower + 1e-6 || price >= upper) && return NaN
        price > black(F, K, T, 5.0, D; call) && return NaN
        lo, hi = 1e-4, 5.0
        for _ in 1:80
            m = (lo + hi) / 2
            black(F, K, T, m, D; call) > price ? (hi = m) : (lo = m)
        end
        (lo + hi) / 2
    end

    "Forward price from put–call parity: F = K + (C − P)/D at the strike where C ≈ P."
    function forward(d)
        T = yearfrac(d); D = exp(-RATE * T)
        c = Dict(o.K => mid(o) for o in chain if o.expiry == d && o.type == 'C')
        p = Dict(o.K => mid(o) for o in chain if o.expiry == d && o.type == 'P')
        Ks = [k for k in keys(c) if haskey(p, k)]
        k = Ks[argmin([abs(c[k] - p[k]) for k in Ks])]
        (; F=k + (c[k] - p[k]) / D, D, T)
    end

    "Implied-vol smile from out-of-the-money options: vector of (log(K/F), iv)."
    function smile(d)
        (; F, D, T) = forward(d)
        pts = [(log(o.K / F), implied_vol(mid(o), F, o.K, T, D; call=o.type == 'C')) for o in chain
               if o.expiry == d && ((o.type == 'P' && o.K < F) || (o.type == 'C' && o.K >= F))]
        sort(filter(x -> isfinite(x[2]), pts))
    end

    function card(items...)
        cells = join(["<div style='flex:1;min-width:150px;padding:10px 14px;border-radius:10px;background:$(c)1f;border:1px solid $(c)66'>" *
                      "<div style='font-size:0.8em;opacity:0.8'>$l</div><div style='font-size:1.55em;font-weight:700'>$v</div></div>"
                      for (l, v, c) in items])
        HTML("<div style='display:flex;flex-wrap:wrap;gap:12px;margin:10px 0'>$cells</div>")
    end
end;

