# ╔═╡ 4b0dbb41-8d52-48f1-942c-3fe860e7a113
mc = let
    (; F, D, T) = forward(intro_exp)
    σ = mc_vol_pct / 100
    z = randn(MersenneTwister(2026), 40_000)
    ST = F .* exp.(-σ^2 * T / 2 .+ σ * sqrt(T) .* z)
    payoff = intro_type == 'C' ? max.(ST .- intro_K, 0) : max.(intro_K .- ST, 0)
    ndays = Dates.value(intro_exp - ASOF)
    μ = log(F / SPOT) / T
    dt = T / ndays
    wide_paths = Vector{Vector{Float64}}()
    paths = map(1:80) do k
        rng = MersenneTwister(k)
        s = Vector{Float64}(undef, ndays + 1); s[1] = SPOT
        wide=copy(s); wide[1]=SPOT
        for i in 1:ndays
            shock=randn(rng)
            s[i+1] = s[i] * exp((μ - σ^2 / 2) * dt + σ * sqrt(dt) * shock)
            wide[i+1] = wide[i] * exp((μ - 0.40^2 / 2) * dt + 0.40 * sqrt(dt) * shock)
        end
        push!(wide_paths,wide)
        s
    end
    wide_ST=F .* exp.(-0.40^2*T/2 .+ 0.40*sqrt(T).*z)
    lo=min(minimum(wide_ST),minimum(minimum,wide_paths),660.)
    hi=max(maximum(wide_ST),maximum(maximum,wide_paths),880.)
    pad=0.05(hi-lo); fixed_limits=(max(0.,lo-pad),hi+pad)
    density_max=1.20exp(0.05^2*T)/(F*0.05*sqrt(2π*T))
    (; F, D, T, σ, ST, payoff, price=D * mean(payoff), days=0:ndays, paths, fixed_limits, density_max)
end;

# ╔═╡ e2acf72f-9e57-4f7a-a0ee-89aed453dd32
let
    itm(s) = intro_type == 'C' ? s > intro_K : s < intro_K
    lo,hi=mc.fixed_limits
    a = plot(xlabel="days from today", ylabel="SPY (\$)", legend=:topleft, ylim=(lo, hi), xlims=(0,maximum(mc.days)), widen=false,
        title="80 possible futures (green = option pays off)")
    for s in mc.paths
        plot!(a, mc.days, s, color=itm(s[end]) ? GREEN : GRAY, alpha=itm(s[end]) ? 0.7 : 0.35, lw=1, label=false)
    end
    hline!(a, [intro_K], color=RED, ls=:dash, lw=2, label="strike \$$(intro_K)")
    edges = range(lo, hi, length=61)
    dens(x) = [count(v -> edges[i] <= v < edges[i+1], x) for i in 1:60] ./ (length(mc.ST) * step(edges))
    box(i, h) = Shape([0, h, h, 0], [edges[i], edges[i], edges[i+1], edges[i+1]])
    hall, hitm = dens(mc.ST), dens(filter(itm, mc.ST))
    b = plot([box(i, hall[i]) for i in 1:60], color=GRAY, alpha=0.45, lw=0, label=false,
        ylim=(lo, hi), xlims=(0,mc.density_max), widen=false, yticks=false, xticks=false, title="where SPY ends", legend=:topright)
    plot!(b, [box(i, hitm[i]) for i in 1:60], color=GREEN, alpha=0.85, lw=0, label=false)
    hline!(b, [intro_K], color=RED, ls=:dash, lw=2, label=false)
    annotate!(b, 0.55maximum(hall), intro_type == 'C' ? hi - 0.06(hi - lo) : lo + 0.06(hi - lo),
        text("$(round(Int, 100count(itm, mc.ST) / length(mc.ST)))% pay off", 9, GREEN))
    plot(a, b, layout=@layout([a{0.75w} b]), size=(860, 400))
end

