# ╔═╡ 5715bd6f-a416-4293-84c2-e2e3444ea7c8
begin
    # Heston characteristic function of log(S_T/F) ("little trap" form, Albrecher et al. 2007)
    function heston_cf(u, T, v0, κ, θ, ξ, ρ)
        ξ = max(ξ, 1e-4)
        iu = im * u
        b = κ - ρ * ξ * iu
        d = sqrt(b^2 + ξ^2 * (iu + u^2))
        g = (b - d) / (b + d)
        e = exp(-d * T)
        C = κ * θ / ξ^2 * ((b - d) * T - 2log((1 - g * e) / (1 - g)))
        Dv = (b - d) / ξ^2 * (1 - e) / (1 - g * e)
        exp(C + Dv * v0)
    end
    function simpson(f, a, b, n)
        h = (b - a) / n
        s = f(a) + f(b)
        for j in 1:n-1
            s += (isodd(j) ? 4 : 2) * f(a + j * h)
        end
        s * h / 3
    end
    # Lewis (2001) single-integral formula for a European call
    function heston_call(F, K, T, D, m::Heston)
        if m.xi == 0
            A = m.kappa == 0 ? m.v0*T :
                m.theta*T + (m.v0-m.theta)*(-expm1(-m.kappa*T))/m.kappa
            return black(F, K, T, sqrt(max(A/T, 0.0)), D)
        end
        k = log(F / K)
        f(u) = real(exp(im * u * k) * heston_cf(u - 0.5im, T, m.v0, m.kappa, m.theta, m.xi, m.rho)) / (u^2 + 0.25)
        U = 12 / sqrt(max(min(m.v0, m.theta), 1e-4) * T) + 50
        D * (F - sqrt(F * K) / π * (simpson(f, 0.0, 20.0, 400) + simpson(f, 20.0, max(U, 40.0), 2000)))
    end
    function heston_iv(F, K, T, D, m::Heston)
        c = heston_call(F, K, T, D, m)
        K < F ? implied_vol(c - D * (F - K), F, K, T, D; call=false) : implied_vol(c, F, K, T, D)
    end
    function heston_skew(T, m::Heston)
        h = 0.02sqrt(max(T, 0.01))
        (heston_iv(1.0, exp(h), T, 1.0, m) - heston_iv(1.0, exp(-h), T, 1.0, m)) / (2h)
    end
end;

# ╔═╡ 10f1bc81-448a-4a9e-a6b2-bc5b50c187fc
let
    panels = map([(h_fit_exp, BLUE)]) do (d, c)
        (; F, D, T) = forward(d)
        s = filter(x -> -0.9 * (0.5sqrt(T) + 0.03) < x[1] < 0.5 * (0.5sqrt(T) + 0.03), smile(d))
        K = F .* exp.(first.(s))
        mkt = 100 .* last.(s)
        model = [100heston_iv(F, k, T, D, heston_now) for k in K]
        err = filter(isfinite, model .- mkt)
        rmse_text = isempty(err) ? "numerically unresolved" : "RMSE $(round(sqrt(mean(err .^ 2)); digits=1)) IV pts · $(length(err))/$(length(K)) valid"
        p = scatter(100K ./ SPOT, mkt, color=c, ms=3, msw=0, label="market",
            title=Dates.format(d, "d u yyyy") * "\n" * rmse_text,
            xlabel="strike / SPY (%)", ylabel="implied vol (%)", xlims=(70,115),ylims=(0,80),widen=false,legend=:topright, titlefontsize=12, top_margin=8Plots.mm)
        plot!(p, 100K ./ SPOT, model, color=:black, lw=2.5, label="Heston (sliders)")
        mark_outside!(p,100K ./ SPOT,model,0,80)
        p
    end
    plot(panels..., layout=(1, 1), size=(860, 400))
end

# ╔═╡ 287d06ca-6f4c-469a-8b22-d3081c8eaee9
begin
    "ATM skew: slope of a quadratic fit of implied vol vs log-moneyness near the money."
    function atm_skew(d)
        s = smile(d); T = yearfrac(d)
        atm = s[argmin(abs.(first.(s)))][2]
        w = max(0.6atm * sqrt(T), 0.006)
        sel = filter(x -> abs(x[1]) <= w, s)
        length(sel) < 4 && return NaN
        x = first.(sel); X = [ones(length(x)) x x .^ 2]
        (X \ last.(sel))[2]
    end
    skew_data = let
        pts = [(yearfrac(d), -atm_skew(d)) for d in sort(unique(o.expiry for o in chain))]
        filter(p -> isfinite(p[2]) && p[2] > 0, pts)
    end
    skew_fit = let
        pts = filter(p -> p[1] >= 10 / 365, skew_data)
        X = [ones(length(pts)) log.(first.(pts))]
        β = X \ log.(last.(pts))
        (; slope=β[2], H=β[2] + 0.5)
    end
end;

# ╔═╡ beb79919-3f22-4af8-a3be-d01d43cf2fde
let
    Ts, sk = first.(skew_data), last.(skew_data)
    p = scatter(365Ts, sk, xscale=:log10, yscale=:log10, color=BLUE, ms=5, msw=0, label="SPY market (9 Oct 2026)",
        xlabel="days to expiry (log scale)", ylabel="|ATM skew| (log scale)",
        title="ATM skew across expiries · fitted H ≈ $(round(skew_fit.H, digits=2))",
        ylims=(0.03,10),xlims=(365minimum(Ts),365maximum(Ts)),widen=false,legend=:bottomleft, xticks=([2, 5, 10, 30, 90, 180, 365], string.([2, 5, 10, 30, 90, 180, 365])))
    tt = exp.(range(log(minimum(Ts)), log(maximum(Ts)), length=60))
    fit = Ts .>= 10 / 365
    anchor = exp(mean(log.(sk[fit]) .- (hurst - 0.5) .* log.(Ts[fit])))
    plot!(p, 365tt, anchor .* tt .^ (hurst - 0.5), color=PURPLE, lw=2.5, label="Power-law guide: slope H − ½ (H = $hurst)")
    hs = [abs(heston_skew(t, heston_now)) for t in tt]
    keep = isfinite.(hs) .& (hs .> 1e-8)
    if any(keep)
        plot!(p, 365tt, ifelse.(keep,hs,NaN), color=:black, lw=2, ls=:dash, label="Heston (your sliders)")
    end
    p
end

